CREATE OR REPLACE FUNCTION public.wa_is_org_conversation(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.whatsapp_conversations WHERE id=_id AND connection_id IS NOT NULL) $$;
REVOKE ALL ON FUNCTION public.wa_is_org_conversation(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.wa_is_org_conversation(uuid) TO authenticated;
ALTER POLICY wa_org_message_boundary ON public.whatsapp_messages USING(NOT public.wa_is_org_conversation(conversation_id) OR public.wa_inbox_access(conversation_id,false)) WITH CHECK(NOT public.wa_is_org_conversation(conversation_id));
CREATE OR REPLACE FUNCTION public.wa_actor_authorized(_conversation uuid,_actor uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.license_active() AND EXISTS(SELECT 1 FROM public.whatsapp_conversations c JOIN public.profiles p ON p.id=_actor WHERE c.id=_conversation AND c.connection_id IS NOT NULL AND p.account_status='active' AND public.is_company_member(_actor,c.company_id) AND public.org_feature_allowed(c.company_id,'whatsapp') AND (public.org_customer_admin(_actor,c.company_id) OR (c.assigned_to=_actor AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_actor AND role IN ('employee','manager')) AND EXISTS(SELECT 1 FROM public.user_access_roles u JOIN public.access_roles r ON r.id=u.role_id WHERE u.user_id=_actor AND 'whatsapp.create'=ANY(r.permissions))))) $$;
REVOKE ALL ON FUNCTION public.wa_actor_authorized(uuid,uuid) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.wa_actor_authorized(uuid,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.wa_send_actor_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.direction='outbound' AND NEW.client_id IS NOT NULL AND NOT public.wa_actor_authorized(NEW.conversation_id,NEW.actor_id) THEN RAISE EXCEPTION 'Reply permission revoked';END IF;RETURN NEW;END $$;
CREATE TRIGGER wa_send_actor_guard BEFORE INSERT ON public.whatsapp_messages FOR EACH ROW EXECUTE FUNCTION public.wa_send_actor_guard();
ALTER PUBLICATION supabase_realtime ADD TABLE public.whatsapp_conversations,public.whatsapp_messages,public.whatsapp_internal_notes;